-- Pattern syntax as Lua 5.1 reads it: in a set, a %class is never the start
-- of a range and a range's end not the start of another ("[%a-z]" and
-- "[a-c-e]" matched nothing); %f[set] frontiers (5.1.5); malformed items
-- raise their error when the matcher reaches them (gopher-lua accepted a
-- trailing '%' and a %b without delimiters, and failed ")" and "%0" when
-- parsing).
local function p(f, ...) print(pcall(function(...) return f(...) end, ...)) end
print(string.gsub("az-_09A", "[%a-z]", "<%0>"))
print(string.gsub("abcde-", "[a-c-e]", "<%0>"))
print(string.gsub("a-_.%d", "[%w-_]", "<%0>"))
print(string.gsub("abd%", "[a-%d]", "<%0>"))
print(string.gsub("]-a^", "[]-a]", "<%0>"))
print(string.gsub("a]b", "[^]]", "<%0>"))
print(string.gsub("THE (quick) fox", "%f[%a]%a+", "W"))
print(string.gsub("hello world", "%f[%w]%w+%f[%W]", "<%0>"))
print(string.find("THE (quick) fox", "%f[%l]"))
print(string.find("abc", "%f[%z]"))
print(string.find("abc", "%f[^%z]"))
print(string.gsub("aaa", "%f[a]", "^"))
print(string.match("x1y22", "%f[%d]%d+"))
print(string.gsub("ab", "%f[%a]*", "<%0>"))
p(string.find, "abc", "%")
p(string.find, "abc", "x%")
p(string.find, "abc", "a%")
p(string.find, "abc", "%b")
p(string.find, "abc", "%ba")
p(string.find, "abc", "x%b")
p(string.find, "abc", "[a")
p(string.find, "abc", "x[a")
p(string.find, "abc", "[%")
p(string.find, "abc", "%f")
p(string.find, "abc", "x%fa")
p(string.find, "abc", "b%fa")
p(string.find, "abc", "(a)%0")
p(string.find, "xbc", "(a)%0")
p(string.match, "abc", ")")
p(string.match, "abc", "x)")
p(string.gsub, "abc", "c)", "")
p(string.gsub, "abc", "d)", "")
local it = string.gmatch("abc", "%")
p(it)
p(it)
local it = string.gmatch("abcd", "c%")
p(it)
p(it)
